import React from "react";
import { Link, useLocation } from "react-router-dom";

/*
 Put a logo at public/assets/logo.png (or change path)
*/
export default function Header() {
  const location = useLocation();
  const navItems = [
    "Home","The School","Admissions","Academics",
    "Extra Curricular","Download","Gallery","Mandatory Disclosure","Contact"
  ];

  return (
    <header className="site-header">
      <div className="topbar">
        <div className="top-left">
          <img src="/assets/logo.png" alt="logo" className="logo" />
          <div className="school-meta">
            <div className="school-name">GANDHI INTERNATIONAL PUBLIC SCHOOL</div>
            <div className="school-sub">CBSE Board Affiliated Co-Ed English Medium Senior Secondary School</div>
          </div>
        </div>

        <div className="top-right">
          <a className="social">👍 Like</a>
          <a className="social">✖ Follow</a>
          <a className="social">▶ YouTube</a>
        </div>
      </div>

      <nav className="main-nav">
        <div className="nav-inner">
          {navItems.map((t, i) => {
            const path = i===0 ? "/" : `/${t.toLowerCase().replace(/\s+/g, "-")}`;
            const active = location.pathname === path || (location.pathname === "/" && i===0);
            return (
              <Link key={t} to={path} className={`nav-item ${active ? "active" : ""}`}>
                {t}
              </Link>
            );
          })}
        </div>
      </nav>
    </header>
  );
}
